"""Composite native product over a locally repaired photographic clean plate.
Original background pixels are preserved before scaling; the product is newly
rendered at 3x linear resolution, not enlarged from the old render.
"""
import bpy,os
from pathlib import Path
R=Path(__file__).resolve().parents[2];OUT=Path(os.environ.get('BOP_ASSET_OUT',R/'public/images/product'));s=bpy.context.scene
s.render.engine='BLENDER_EEVEE';s.render.resolution_x=4608;s.render.resolution_y=3072;s.render.resolution_percentage=100;s.render.image_settings.file_format='PNG';s.render.image_settings.color_mode='RGBA';s.view_settings.view_transform='Standard';s.view_settings.look='None';s.view_settings.exposure=0;s.view_settings.gamma=1
ng=bpy.data.node_groups.new('V68 source-faithful composition','CompositorNodeTree');ng.interface.new_socket(name='Image',in_out='OUTPUT',socket_type='NodeSocketColor');s.compositing_node_group=ng;s.use_nodes=True;s.render.use_compositing=True;n=ng.nodes;l=ng.links
# A tiny empty render supplies the compositor context; the image nodes supply
# all final pixels. No product geometry is generated by this compositor.
def img(path):
 o=n.new('CompositorNodeImage');o.image=bpy.data.images.load(str(path));return o
old=img(R/'public/images/product/platform-strap-reference-v18.png');clean=img(R/'docs/v68/station-clean-plate.png');mask=img(R/'design/v68-station-repair-mask.png');product=img(OUT/'platform-product-native-v68.png')
s.render.resolution_x=product.image.size[0];s.render.resolution_y=product.image.size[1];factor=product.image.size[0]/1536
mix=n.new('ShaderNodeMix');mix.data_type='RGBA';mix.blend_type='MIX';l.new(mask.outputs['Image'],mix.inputs[0]);l.new(old.outputs['Image'],mix.inputs[6]);l.new(clean.outputs['Image'],mix.inputs[7]);over=n.new('CompositorNodeAlphaOver');over.inputs['Factor'].default_value=1;scale=n.new('CompositorNodeScale');scale.inputs['Type'].default_value='Relative';scale.inputs['X'].default_value=factor;scale.inputs['Y'].default_value=factor;l.new(mix.outputs[2],scale.inputs['Image']);l.new(scale.outputs['Image'],over.inputs['Background']);l.new(product.outputs['Image'],over.inputs['Foreground']);out=n.new('NodeGroupOutput');l.new(over.outputs[0],out.inputs[0])
s.render.filepath=str(OUT/'platform-native-v68.png');bpy.ops.render.render(write_still=True)
